import { chromium } from 'playwright';
const b = await chromium.launch();
const c = await b.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
await c.addInitScript(() => { localStorage.setItem('thai-days-guide-v1', '1'); localStorage.setItem('thai-days-place-size-v1', 'big'); });
const p = await c.newPage();
await p.goto('http://localhost:8765/'); await p.waitForTimeout(1500);
const tab = async t => { await p.evaluate(t => document.querySelector(`[data-tab="${t}"]`).click(), t); await p.waitForTimeout(500); };
const settle = async () => { await p.evaluate(() => scrollTo(0, 0)); await p.waitForTimeout(400); await p.evaluate(async () => { for (let y = 0; y < 2600; y += 400) { scrollTo(0, y); await new Promise(r => setTimeout(r, 250)); } scrollTo(0, 0); }); await p.waitForTimeout(3000); };
const shot = async (name, sel) => { const top = await p.$eval(sel, e => e.getBoundingClientRect().top + scrollY - 70); await p.evaluate(y => scrollTo(0, y), top); await p.waitForTimeout(1500); await p.screenshot({ path: `.preview/shots/${name}.png`, clip: { x: 0, y: top, width: 390, height: 2200 }, fullPage: true }); };
await tab('discover'); await p.click('#discover [data-kind="chula"]'); await settle(); await shot('1-chula', '#discover .cat-chips');
await p.click('#discover [data-kind="see"]'); await settle(); await shot('2-see', '#discover .places');
await p.click('#discover [data-kind="eat"]'); await settle(); await shot('3-eat', '#discover .places');
await tab('food'); await settle(); await shot('4-food', '#food');
await p.selectOption('#food .city-filter', '大城'); await p.waitForTimeout(300); await settle(); await shot('5-food-ayutthaya', '#food .places');
await b.close();
